Q: PHP/MYSQLi - Display last date query A: <p>Try this whit &quot;ORDER BY&quot;:</p>
<pre><code>$query = &quot;SELECT date_visited, page_title,count(*) FROM table WHERE ip ORDER BY page_title ASC&quot;;
$result = mysqli_query($link,$query) or die(mysqli_error($link). &quot;Q=&quot;.$query);
if(!$result == 0) {
    while ($row = mysqli_fetch_array($result)) {
        $dataList_br .= '&lt;tr&gt;
                            &lt;td&gt;' .$row['date_visited']. '&lt;/td&gt;
                            &lt;td&gt;' .$row['page_title']. '&lt;/td&gt;
                            &lt;td&gt;' .$row['count(*)']. '&lt;/td&gt;
                        &lt;/tr&gt;';
    }
} else {
    $dataList_br .= '&lt;p class=&quot;warning&quot;&gt;No data found in database.&lt;/p&gt;';
}
</code></pre>

Q: Using localization in .NET MAUI picker A: <p>Here is a possible solution that uses <em>Behaviours</em> and <em>WeakReferenceMessenger</em>. Not all that pretty but has possibilities.</p>
<p>Requirement is that you have made the resources for the different language you want.</p>
<p>Let us start with the implementation. We got a picker and a radio buttons group. The picker got a Behavior that is going to do all the magic.</p>
<pre class="lang-xml prettyprint-override"><code>&lt;Picker x:Name=&quot;MyPicker&quot; Title=&quot;{x:Static localization:AppResources.PickerTitle}&quot;&gt;
   &lt;Picker.Behaviors&gt;
      &lt;local:LocalizedPickerBehavior /&gt;
   &lt;/Picker.Behaviors&gt;
&lt;/Picker&gt;
&lt;local:RadioButtonGroup /&gt;
</code></pre>
<p>We create the behaviour. Here we initialize the Messenger that will tell the Behaviour that we have changed language.</p>
<pre class="lang-cs prettyprint-override"><code>public class LocalizedPickerBehavior : Behavior&lt;Picker&gt;
{
    protected override void OnAttachedTo(Picker picker)
    {
        base.OnAttachedTo(picker);

        // Set the ItemsSource of the Picker
        SetItemsSource(picker);


        // Listen for the LanguageChanged notification
        WeakReferenceMessenger.Default.Register&lt;LocalizedPickerBehaviorMessage&gt;(this, (recipient, message) =&gt; {
            var culture = new CultureInfo(message.Value);
            CultureInfo.CurrentUICulture = culture;
            SetItemsSource(picker);
        });
    }

    private void SetItemsSource(Picker picker)
    {
        var option1 = AppResources.Option1;
        var option2 = AppResources.Option2;
        var option3 = AppResources.Option3;

        picker.Title = AppResources.PickerTitle;
        var currentIndex = picker.SelectedIndex;
        picker.ItemsSource = new List&lt;string&gt; { option1, option2, option3 };
        picker.SelectedIndex = currentIndex;
    }

    protected override void OnDetachingFrom(Picker picker)
    {
        base.OnDetachingFrom(picker);

        picker.ItemsSource = null;

        WeakReferenceMessenger.Default.Unregister&lt;LocalizedPickerBehavior&gt;(this);
    }
}
</code></pre>
<p>For the messenger we need a message that we send with the language we want to change to.</p>
<pre class="lang-cs prettyprint-override"><code>public class LocalizedPickerBehaviorMessage : ValueChangedMessage&lt;string&gt;
{
    public LocalizedPickerBehaviorMessage(string lang) : base(lang)
    {
    }
}
</code></pre>
<p>And we finish off with a simple radio button that sends the message to our behaviour.</p>
<pre class="lang-cs prettyprint-override"><code>public class RadioButtonGroup : StackLayout
{
    public RadioButton RadioButton1 { get; private set; }
    public RadioButton RadioButton2 { get; private set; }

    public RadioButtonGroup()
    {
        Orientation = StackOrientation.Horizontal;
        RadioButton1 = new RadioButton { Content = &quot;English&quot; };
        RadioButton2 = new RadioButton { Content = &quot;Swedish&quot; };

        RadioButton1.CheckedChanged += OnRadioButtonCheckedChanged;
        RadioButton2.CheckedChanged += OnRadioButtonCheckedChanged;

        Children.Add(RadioButton1);
        Children.Add(RadioButton2);

        RadioButton1.IsChecked = true;
    }

    private void OnRadioButtonCheckedChanged(object sender, CheckedChangedEventArgs e)
    {
        var radioButton = (RadioButton)sender;

        if (radioButton == RadioButton1 &amp;&amp; RadioButton1.IsChecked)
        {
            RadioButton2.IsChecked = false;
            WeakReferenceMessenger.Default.Send(new LocalizedPickerBehaviorMessage(&quot;en&quot;));
        }
        else if (radioButton == RadioButton2 &amp;&amp; RadioButton2.IsChecked)
        {
            RadioButton1.IsChecked = false;
            WeakReferenceMessenger.Default.Send(new LocalizedPickerBehaviorMessage(&quot;sv&quot;));
        }
    }
}
</code></pre>
